// Public data tools + real isolated Node workers. Generated bytes only; no native execution.
import assert from 'node:assert/strict';
import { AsyncLocalStorage } from 'node:async_hooks';
import { createCipheriv, createHash } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createAnalysisService, defineAnalysisTools } from '../analysis_tools.js';

const scratch = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), 'ig5-discovery-host-'));
const cfg = { artifactDir: path.join(scratch, 'artifacts'), defaultEngine: 'ghidra' };
const inline = bytes => ({ encoding: 'hex', data: bytes.toString('hex') });
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const target = path.join(scratch, 'generated sample.exe');
const session = { target, engine: 'ghidra', artifactId: 'generated-artifact', attachmentId: 'generated-attachment', sha256: 'a'.repeat(64), dbRevision: 3, ready: true, data: Buffer.alloc(2048) };
const mgr = { session, scope: new AsyncLocalStorage(), queue: Promise.resolve(), locked: 0, calls: [],
  checkCancelled() { if (mgr.scope.getStore()?.signal?.aborted) throw Object.assign(new Error('Cancelled'), { code: 'ABORT_ERR' }); },
  get(value, engine) { return path.resolve(value) === session.target && engine === session.engine ? session : undefined; },
  alive(value) { return value?.ready === true; },
  evidence(value) { return { engine: value.engine, artifactId: value.artifactId, attachmentId: value.attachmentId, sha256: value.sha256, dbRevision: value.dbRevision }; },
  withSessions(values, run) { assert.deepEqual(values, [session]); const pending = mgr.queue.catch(() => {}).then(async () => { mgr.locked++; try { return await run(); } finally { mgr.locked--; } }); mgr.queue = pending; return pending; },
  async rpc(value, method, options) { assert.equal(mgr.locked, 1); assert.equal(method, 'bytes'); assert.equal(value, session); mgr.calls.push(options); const at = Number(BigInt(options.ea) - 0x8000000000001000n); return { hex: session.data.subarray(at, at + options.size).toString('hex') }; },
};
const service = createAnalysisService(mgr, cfg); mgr.analysis = service;
const definitions = defineAnalysisTools(mgr, cfg, value => value), tools = new Map(definitions.map(tool => [tool.name, tool]));
const call = (kind, args) => tools.get('ig5_' + kind).execute(args);
const rejects = (run, code) => assert.rejects(run, error => error.code === code);
const cases = [];
async function test(name, body) { try { await body(); cases.push({ name, ok: true }); console.log('PASS', name); } catch (error) { cases.push({ name, ok: false, error: error.stack }); console.error('FAIL', name, error.stack); } }
function frame(id, text) { const payload = Buffer.from(text); const result = Buffer.alloc(payload.length + 7); result.writeUInt16BE(result.length - 2, 0); result[2] = 9; result.writeUInt32BE(id, 3); payload.copy(result, 7); return result; }
const messages = [frame(101, 'first generated payload'), frame(102, 'second generated message'), frame(103, 'third different text payload'), frame(104, 'fourth validation message')];
const clear = Buffer.concat(messages), key = Buffer.from('1956973cb40ea712d88925f6abfe814d', 'hex'), iv = Buffer.from('534b681921fa386408125fed', 'hex'), aad = Buffer.from('IG5 generated discovery');
const enc = createCipheriv('aes-128-gcm', key, iv); enc.setAAD(aad); const cipher = Buffer.concat([enc.update(clear), enc.final()]), tag = enc.getAuthTag();
const material = Buffer.alloc(128, 0x42); key.copy(material, 64); const materialPath = path.join(scratch, 'explicit key material.bin'); fs.writeFileSync(materialPath, material);
cipher.copy(session.data); material.copy(session.data, 1024);
const aes = { kind: 'aes-gcm', iv: inline(iv), tag: inline(tag), aad: inline(aad), padding: 'none' };
const source = (offset, size) => ({ source: { target, engine: 'ghidra', ea: '0x' + (0x8000000000001000n + BigInt(offset)).toString(16), size, expected_revision: 3 } });
let recovered, restored, inferred, keyRef, staticRecovered;
const noSecrets = value => { const text = JSON.stringify(value); for (const bytes of [key, iv, tag, aad, material]) { assert(!text.includes(bytes.toString('hex')), 'Raw key/AES/material leaked in a report'); assert(!text.includes(bytes.toString('base64')), 'Raw key/AES/material leaked in a report'); } };

await test('Existing two tools add recover/infer/ref/delimiter schemas with correct required arrays', async () => {
  assert.equal(definitions.length, 2); assert(tools.get('ig5_crypto').parameters.properties.action.enum.includes('recover'));
  assert(tools.get('ig5_protocol').parameters.properties.action.enum.includes('infer'));
  assert.equal(tools.get('ig5_crypto').parameters.properties.recovery.properties.key_source.properties.source.required[0], 'target');
  assert(tools.get('ig5_protocol').parameters.properties.framing.properties.type.enum.includes('delimiter'));
  function compliant(value) { if (!value || typeof value !== 'object') return; assert.notEqual(value.required, true); if (Object.hasOwn(value, 'required')) assert(Array.isArray(value.required)); for (const item of Object.values(value)) compliant(item); }
  definitions.forEach(tool => compliant(tool.parameters));
});
