await test('Public framing schemas execute canonical varint and TLV inference-to-decode with independent holdout', async () => {
  const schema = tools.get('ig5_protocol').parameters.properties.framing.properties;
  assert(schema.type.enum.includes('varint-prefix')); assert(schema.type.enum.includes('tlv')); assert.equal(schema.maxBytes.maximum, 5);
  const leb = n => { const bytes = []; do { const byte = n & 127; n >>>= 7; bytes.push(byte | (n ? 128 : 0)); } while (n); return Buffer.from(bytes); };
  const wrapVarint = text => { const bytes = Buffer.from(text); return Buffer.concat([leb(bytes.length), bytes]); };
  const wrapTlv = (tag, text) => { const bytes = Buffer.from(text); return Buffer.concat([Buffer.from([tag, bytes.length]), bytes]); };
  for (const [type, samples, holdout] of [
    ['varint-prefix', ['short varint', 'long varint '.repeat(12), 'third body'].map(wrapVarint), wrapVarint('separate holdout payload')],
    ['tlv', [wrapTlv(1, 'one'), wrapTlv(2, 'second payload'), wrapTlv(3, 'three bytes')], wrapTlv(4, 'fourth unseen message')],
  ]) {
    const stream = Buffer.concat(samples), found = await call('protocol', { action: 'infer', input: inline(stream), inference: { format: 'stream', boundary: 'message-start', holdout_samples: [inline(holdout)] } });
    const candidate = service.artifacts.get(found.result_id).result.inference.candidates.find(row => row.framing.type === type && row.decodeInput.startOffset === 0);
    assert(candidate, `${type} candidate missing`); assert.equal(candidate.validation.verified, true);
    const decoded = await call('protocol', { action: 'decode', input: { ref: found.input.ref, result_id: found.result_id }, offset: candidate.decodeInput.startOffset, length: candidate.decodeInput.byteLength, framing: candidate.framing, schema: candidate.schema });
    assert.equal(decoded.value.complete, true); assert.equal(decoded.value.frames.length, 3);
  }
});
